-- Reproducible open-model validation generated by:
-- npm run grid:validate:c1
-- This is solver evidence only and is deliberately not linked to a map node.

insert into public.grid_model_versions (
  id, model_key, version, validation_class, source_name, source_url, licence,
  model_sha256, model_format, element_counts, provenance
) values (
  'c1000000-0000-4000-8000-000000000001',
  'simbench:1-MV-urban--0-sw',
  'simbench-open-model-v1',
  'synthetic_demonstration',
  'SimBench',
  'https://simbench.de/en/download/',
  'ODbL-1.0',
  '6786fe43a4a4567928b01ca582403bb4820aa4ef852ffc6af290e4baf685da95',
  'simbench-pandapower',
  '{"buses":144,"lines":147,"transformers":2,"loads":139,"generators":135}'::jsonb,
  '{"benchmark_code":"1-MV-urban--0-sw","geographic_truth":"representative German benchmark; not a real location"}'::jsonb
) on conflict (model_key, version, model_sha256) do nothing;

insert into public.grid_model_connection_points (
  id, model_version_id, model_bus_id, match_state, match_evidence
) values (
  'c1000000-0000-4000-8000-000000000002',
  'c1000000-0000-4000-8000-000000000001',
  'bus-84',
  'benchmark_only',
  '{"public_label":"Open benchmark solver validation — not location capacity"}'::jsonb
) on conflict (model_version_id, model_bus_id) do nothing;

insert into public.network_study_runs (
  id, model_version_id, connection_point_id, study_type, status,
  validation_class, solver, solver_version, input_sha256, assumptions, result,
  limitations, started_at, completed_at
) values (
  'c1000000-0000-4000-8000-000000000003',
  'c1000000-0000-4000-8000-000000000001',
  'c1000000-0000-4000-8000-000000000002',
  'capacity', 'succeeded', 'synthetic_demonstration',
  'pandapower-newton-raphson', '3.5.4',
  '6786fe43a4a4567928b01ca582403bb4820aa4ef852ffc6af290e4baf685da95',
  '{"connection_bus":"bus-84","study_year":2026,"voltage_limits_pu":[0.95,1.05],"thermal_limit_percent":100,"search_tolerance_mw":0.1}'::jsonb,
  '{"converged":true,"base_case_capacity_mw":5.812,"firm_import_capacity_mw":5.812,"binding_case":"base_case","binding_constraint":"line_thermal_loading","contingencies":[],"model_id":"simbench:1-MV-urban--0-sw","model_version":"simbench-open-model-v1","validation_class":"synthetic_demonstration"}'::jsonb,
  '["C1 evaluates steady-state AC thermal and voltage constraints only.","No reviewed contingency list is present in this benchmark run.","This representative benchmark result is not location capacity."]'::jsonb,
  '2026-08-08T14:29:24.299111+00:00',
  '2026-08-08T14:29:24.299111+00:00'
) on conflict (model_version_id, connection_point_id, study_type, input_sha256)
do update set
  solver_version = excluded.solver_version,
  assumptions = excluded.assumptions,
  result = excluded.result,
  limitations = excluded.limitations,
  completed_at = excluded.completed_at;
